theme.css:
/* theme: Midterm Surge | A blue wave lifts stocks and gold while oil plunges — a day of political victory and market euphoria. */
/* mood: good */
/* layout: hero=poster; political-news=lede/feature; financial-news=stat/grid-3; entertainment-news=tile/masonry; sports=numbered/grid-3; music-releases=plain/stack; stock-analysis=banner/grid-3; outlook=timeline/stack */

.diary-page {
  --paper: #e1f2e5;
  --paper-alt: #d2e8d8;
  --ink: #0d2e1a;
  --ink-soft: #1e4a2c;
  --muted: #3a6b4a;
  --accent: #11652f;
  --accent-ink: #f0faf2;
  --rule: #b7d6c0;
  --font-display: var(--ff-unbounded), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-inter), system-ui, sans-serif;
}

.diary-page[data-hero="poster"] .diary-hero {
  background: linear-gradient(135deg, #0e4a22 0%, #11652f 60%, #0f5a2a 100%);
  border-bottom: 8px solid var(--accent);
  position: relative;
}

.diary-page[data-hero="poster"] .diary-hero::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    repeating-linear-gradient(
      45deg,
      transparent 0 18px,
      rgb(255 255 255 / 0.04) 18px 19px
    );
  pointer-events: none;
}

.diary-page[data-hero="poster"] .diary-hero-inner {
  position: relative;
  z-index: 1;
  padding-block: 4rem 5rem;
}

.diary-page[data-hero="poster"] .diary-kicker {
  color: var(--accent-ink);
  font-weight: 700;
}

.diary-page[data-hero="poster"] .diary-title {
  font-size: clamp(3rem, 10vw, 7.5rem);
  text-transform: uppercase;
  letter-spacing: 0.02em;
  text-shadow: 0 4px 0 rgb(0 0 0 / 0.15);
}

.diary-page[data-hero="poster"] .diary-summary {
  font-family: var(--font-ui);
  font-size: 1rem;
  max-width: 36rem;
  line-height: 1.7;
}

.diary-page[data-hero="poster"] .diary-theme-name {
  background: var(--accent-ink);
  color: var(--accent);
}

.diary-page[data-hero="poster"] .diary-crumbs a {
  color: var(--accent-ink);
  opacity: 0.85;
}

.diary-page .diary-toc-link,
.diary-page .diary-toc-top,
.diary-page .diary-toc-bottom {
  border-left-color: var(--rule);
}

.diary-page .diary-section {
  border-top: 2px solid var(--accent);
}

.diary-page .diary-section-head {
  border-bottom: 3px solid var(--accent);
  padding-bottom: 0.75rem;
  margin-bottom: 2rem;
}

.diary-page .diary-section-number {
  font-size: 2rem;
  font-weight: 700;
  line-height: 1;
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-size: clamp(1.5rem, 3vw, 2rem);
}

.diary-page .diary-card--lede .diary-card-lede {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 400;
  letter-spacing: 0.01em;
  color: var(--ink);
  border-left: 5px solid var(--accent);
}

.diary-page .diary-card--stat .diary-card-inner {
  padding: 1.75rem;
  border-top: 5px solid var(--accent);
  background: linear-gradient(to bottom, transparent 0%, rgb(17 101 47 / 0.06) 100%);
}

.diary-page .diary-card-figure {
  font-size: clamp(2.5rem, 12cqi, 4rem);
  color: var(--accent);
}

.diary-page .diary-card--tile .diary-card-inner {
  background: linear-gradient(145deg, var(--paper-alt), #c4e0cd);
  border-left: 4px solid var(--accent);
  padding: 2rem;
}

.diary-page .diary-card--numbered .diary-card-index {
  font-family: var(--font-display);
  font-weight: 700;
  color: var(--accent);
  font-size: 3.5rem;
  text-shadow: 2px 2px 0 rgb(17 101 47 / 0.15);
}

.diary-page .diary-card--banner .diary-card-title {
  background: linear-gradient(90deg, var(--accent), #0f5a2a);
  font-family: var(--font-display);
  font-weight: 700;
  letter-spacing: 0.04em;
  padding: 1rem 1.25rem;
}

.diary-page .diary-card--banner .diary-card-body {
  padding: 1.75rem;
}

.diary-page .diary-card--timeline .diary-card-inner::before {
  background: linear-gradient(to bottom, var(--accent), var(--rule));
  width: 3px;
}

.diary-page .diary-card--timeline .diary-card-inner::after {
  background: var(--accent);
  box-shadow: 0 0 0 5px rgb(17 101 47 / 0.2);
  width: 0.9rem;
  height: 0.9rem;
  left: -0.05rem;
}

.diary-page .diary-card-thread {
  border-color: var(--accent);
  color: var(--accent);
  background: rgb(17 101 47 / 0.06);
  border-radius: 4px;
  padding: 0.3rem 0.8rem;
}

.diary-page .diary-markets-wrap {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  border-radius: 8px;
  padding: 1.5rem;
}

.diary-page .diary-spark {
  background: var(--paper);
  border-color: var(--rule);
  border-left: 3px solid var(--accent);
}

.diary-page .diary-spark.is-up .diary-spark-change {
  color: var(--accent);
}

.diary-page .diary-spark.is-down .diary-spark-change {
  color: var(--accent);
  opacity: 0.7;
}

.diary-page .diary-footer {
  border-top: 3px solid var(--accent);
  background: var(--paper-alt);
  margin-top: 0;
  padding-top: 2rem;
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

.diary-page .diary-prose a {
  border-bottom: 2px solid rgb(17 101 47 / 0.3);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
  width: 0.75rem;
  height: 3px;
  border-radius: 2px;
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  background: rgb(17 101 47 / 0.05);
  padding: 1rem 1.25rem;
  border-radius: 0 8px 8px 0;
}

.diary-page .diary-prose h3 {
  color: var(--accent);
}

.diary-page .diary-prose h4 {
  color: var(--ink);
  border-bottom: 1px solid var(--rule);
  padding-bottom: 0.3rem;
}

.diary-page .diary-footer-prev,
.diary-page .diary-footer-next {
  padding: 0.5rem 1rem;
  border: 1px solid var(--accent);
  border-radius: 999px;
  color: var(--accent) !important;
  transition: background 200ms, color 200ms;
}

.diary-page .diary-footer-prev:hover,
.diary-page .diary-footer-next:hover {
  background: var(--accent);
  color: var(--accent-ink) !important;
}

.diary-page .diary-toc-link .diary-toc-number {
  color: var(--accent);
  font-weight: 700;
}

@media (min-width: 1024px) {
  .diary-page .diary-toc {
    border-right: 2px solid var(--rule);
    padding-right: 1rem;
  }
}
